const isDemoBooking = (booking) => {
  if (!booking) return false;
  const demoPatterns = [
    "demo",
    "Demo",
    "DEMO",
    "test",
    "Test",
    "TEST",
    "example",
    "Example"
  ];
  const fieldsToCheck = [
    booking.id,
    booking._id,
    booking.userId,
    booking.customer_id,
    booking.contactDetails?.phone,
    booking.contactDetails?.name,
    booking.address,
    booking.service,
    ...booking.services || []
  ];
  return fieldsToCheck.some((field) => {
    if (!field) return false;
    const fieldStr = String(field).toLowerCase();
    return demoPatterns.some(
      (pattern) => fieldStr.includes(pattern.toLowerCase())
    );
  });
};
const filterProductionBookings = (bookings) => {
  if (!Array.isArray(bookings)) return [];
  return bookings.filter((booking) => !isDemoBooking(booking));
};

